/* =========================
   CONFIG
========================= */

const blogUrl = "https://www.jkdmm.in";

const CACHE_KEY = "jkdmm_home_data";

const CACHE_TIME_KEY = "jkdmm_home_cache_time";

const CACHE_DURATION = 1000 * 60 * 30;

/* =========================
   ADSENSE LAZY LOAD
========================= */



/* =========================
   HELPERS
========================= */

function getLink(p) {

  return p.link.find(
    x => x.rel === "alternate"
  ).href;

}

function isNew(d) {

  return (
    (new Date() - new Date(d))
    /
    (1000 * 60 * 60 * 24)
  ) <= 5;

}

function formatDate(d) {

  return new Date(d).toLocaleDateString(
    "en-IN",
    {
      day:"2-digit",
      month:"short",
      year:"numeric"
    }
  );

}

function hasLabel(post,label) {

  return (
    post.category &&
    post.category.some(c =>
      c.term.toLowerCase().includes(
        label.toLowerCase()
      )
    )
  );

}

function setHTML(id, html) {

  const el = document.getElementById(id);

  if(el){
    el.innerHTML = html;
  }

}

/* =========================
   RENDER
========================= */

function renderAll(posts){

  let grouped = {
    recruitment:[],
    result:[],
    admit:[],
    editorial:[]
  };

  posts.forEach(p=>{

    if(hasLabel(p,"recruitment")){
      grouped.recruitment.push(p);
    }

    if(hasLabel(p,"result")){
      grouped.result.push(p);
    }

    if(hasLabel(p,"admit card")){
      grouped.admit.push(p);
    }

    if(hasLabel(p,"editorial")){
      grouped.editorial.push(p);
    }

  });

  /* GRID */

  let grid = "";

  grouped.recruitment
    .slice(0,6)
    .forEach(p=>{

      let n = isNew(p.published.$t)
        ? '<span class="jk-new">NEW</span>'
        : '';

      grid += `
      <a href="${getLink(p)}">
        👉 ${p.title.$t} ${n}
      </a>`;

    });

  setHTML("jobGrid",grid);

  /* TRENDING */

  let trending = "";

  grouped.recruitment
    .slice(0,5)
    .forEach(p=>{

      trending += `
      <a href="${getLink(p)}">
        🔥 ${p.title.$t}
      </a> | `;

    });

  setHTML("trending",trending);

  /* LIST */

  function renderList(arr,id,limit){

    let html = "";

    arr.slice(0,limit).forEach(p=>{

      let n = isNew(p.published.$t)
        ? '<span class="jk-new">NEW</span>'
        : '';

      html += `
      <li>
        <a href="${getLink(p)}">
          ${p.title.$t}
        </a>
        ${n}
      </li>`;

    });

    setHTML(id,html);

  }

  renderList(
    grouped.result,
    "result",
    6
  );

  renderList(
    grouped.admit,
    "admit",
    6
  );

  renderList(
    grouped.recruitment,
    "jobs",
    6
  );

  /* EDITORIAL */

  let ed = "";

  grouped.editorial
    .slice(0,6)
    .forEach(p=>{

      ed += `
      <li>
        <a href="${getLink(p)}">
          ${p.title.$t}
        </a>

        <span class="jk-date">
          (${formatDate(p.published.$t)})
        </span>
      </li>`;

    });

  setHTML("editorial",ed);

   /* =========================
   SIDEBAR DEADLINE
========================= */

let deadlineHTML = "";
let deadlineCount = 0;

grouped.recruitment.forEach(p=>{

  if(deadlineCount >= 5) return;

  let text = "";

  if(p.content && p.content.$t){
    text = p.content.$t;
  }else if(p.summary && p.summary.$t){
    text = p.summary.$t;
  }else{
    text = p.title.$t;
  }

  text = text.replace(/<[^>]*>/g," ");

  let match = text.match(
    /([0-9]{1,2})[.\-/]([0-9]{1,2})[.\-/]([0-9]{4})/
  );

  if(!match) return;

  let d = parseInt(match[1]);
  let m = parseInt(match[2]) - 1;
  let y = parseInt(match[3]);

  let lastDate = new Date(y,m,d);

  let today = new Date();

  today.setHours(0,0,0,0);

  let diff =
    (lastDate - today)
    /
    (1000*60*60*24);

  if(diff >= 0 && diff <= 7){

    deadlineHTML += `
    <li>
      <a href="${getLink(p)}">
        🔺 ${p.title.$t.substring(0,70)}
      </a>

      <br>

      <span class="deadlineDate">
        Last Date:
        ${lastDate.toLocaleDateString("en-GB")}
      </span>
    </li>`;

    deadlineCount++;

  }

});

setHTML(
  "sidebarDeadline",
  deadlineHTML || "<li>No urgent jobs</li>"
);

/* =========================
   SIDEBAR TRENDING
========================= */

let sideTrend = "";

grouped.recruitment
  .slice(0,5)
  .forEach(p=>{

    sideTrend += `
    <li>
      <a href="${getLink(p)}">
        ☛ ${p.title.$t}
      </a>
    </li>`;

  });

setHTML(
  "sidebarTrending",
  sideTrend
);

/* =========================
   SIDEBAR UPDATES
========================= */

let sideUpdates = "";

let updateCount = 0;

posts.forEach(p=>{

  if(updateCount >= 5) return;

  if(
    hasLabel(p,"result") ||
    hasLabel(p,"admit")
  ){

    sideUpdates += `
    <li>
      <a href="${getLink(p)}">
        ➣ ${p.title.$t}
      </a>
    </li>`;

    updateCount++;

  }

});

setHTML(
  "sidebarUpdates",
  sideUpdates || "<li>No updates</li>"
);

/* =========================
   SIDEBAR EDITORIAL
========================= */

let sideEd = "";

grouped.editorial
  .slice(0,4)
  .forEach(p=>{

    sideEd += `
    <li>
      <a href="${getLink(p)}">
        ✍ ${p.title.$t}
      </a>
    </li>`;

  });

setHTML(
  "sidebarEditorial",
  sideEd
);

}

/* =========================
   JSONP LOAD
========================= */

function loadJSONP(url,callbackName){

  let s = document.createElement("script");

  s.src = url + "&callback=" + callbackName;

  document.body.appendChild(s);

}

/* =========================
   MAIN LOGIC
========================= */

(function(){

  let cachedData =
    localStorage.getItem(CACHE_KEY);

  let cacheTime =
    localStorage.getItem(CACHE_TIME_KEY);

  if(
    cachedData &&
    cacheTime &&
    (
      Date.now() - cacheTime
      <
      CACHE_DURATION
    )
  ){

    renderAll(
      JSON.parse(cachedData)
    );

  }

  const cb = "home_" + Date.now();

  window[cb] = function(d){

    if(
      !d.feed ||
      !d.feed.entry
    ) return;

    localStorage.setItem(
      CACHE_KEY,
      JSON.stringify(d.feed.entry)
    );

    localStorage.setItem(
      CACHE_TIME_KEY,
      Date.now()
    );

    renderAll(d.feed.entry);

  };

  loadJSONP(
    `${blogUrl}/feeds/posts/default?alt=json-in-script&max-results=20`,
    cb
  );

})();
